// 当前书源版本号，切勿修改，否则影响更新的识别
const localVersion = '5.9.26';

let controlUrl = host[0];

function login(flag) {
    if (flag == undefined) {
        result = JSON.parse(source.getLoginInfo())
    } else {
        java.longToast("\n\n💞正在登录中...")
        putLoginInfo(JSON.stringify(result))
    }
    let base_url = getArgument('server') || host[0]
    let zdyserver = String(result['自定义服务器(可不填)']);
    if (zdyserver.includes('http')) {
        setArgument('server', zdyserver);
        if (getKey(String(cookie.getCookie(base_url)))) {
            let cookies = cookie.getCookie(base_url)
            try {
                cookie.removeCookie(base_url)
            } catch (e) {}
            cookie.setCookie(zdyserver, cookies)
        }
        java.toast(`\n\n当前服务器为自定义服务器\n${zdyserver}\n\n切换服务器请先清空服务器地址中的数据`);
    }
    let configuredPlcolor = String(result['自定义评论颜色(可不填)'] || '').trim();
    let plcolor = configuredPlcolor || '#A7A7A7';
    setArgument('plcolor', plcolor);
    let zdysources = String(result['自定义搜索源(多个用英文,分割)'] || '');
    if (zdysources) {
        setArgument('sources', zdysources);
    };
    base_url = getArgument('server')
    let register_email = String(result['邮箱'] || '').trim()
    let password = String(result['密码'] || '').trim()
    let key = String(result['密钥'] || '').trim()
    if (key === 'undefined' || key === 'null') key = ''

    // 主动点击登录时，邮箱或密码为空不允许使用残留密钥登录。
    if (flag && (!register_email || !password)) {
        try {
            if (result && typeof result === 'object') {
                delete result['密钥'];
                putLoginInfo(JSON.stringify(result));
            }
        } catch (e) {}
        java.toast("\n\n⛔️请先填写邮箱和密码");
        return;
    }

    if ((register_email && password || key) && !String(getKey(String(cookie.getCookie(base_url))))) {
        try {
            cookie.removeCookie(base_url)
        } catch (e) {}
        let deviceKey = '';
        try {
            deviceKey = java.deviceID();
        } catch (e) {
            deviceKey = java.androidId();
        };
        let deviceId = deviceKey;
        if (register_email && password) {
            let options = JSON.stringify({
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    register_email: result['邮箱'],
                    password: result['密码']
                })
            })
            try {
                let data = JSON.parse(java.ajax(`${base_url}/login_api,${options}`))
                if (data.code == 0) {
                    //java.toast(deviceId)
                    java.toast("\n\n✅️登录成功")
                    cookie.setCookie(base_url, `qttoken=${data.key};deviceId=${deviceId}`);
                    for (var _h = 0; _h < host.length; _h++) { try { cookie.setCookie(host[_h], `qttoken=${data.key};deviceId=${deviceId}`); } catch(_e){} }
                    result['密钥'] = data.key
                    setArgument('qttoken', data.key);
                    putLoginInfo(JSON.stringify(result))
                } else {
                    java.toast('\n\n💔' + data.msg || "登录失败，请重试！")
                }
            } catch (e) {
                java.toast("\n\n💔登录失败，请重试！\n" + e.message)
            }
        } else {
            cookie.setCookie(base_url, `qttoken=${key};deviceId=${deviceId}`)
            let res = java.ajax(`${base_url}/user_api,{"method":"POST","headers":{"cookie":"${cookie.getCookie(base_url)}"}}`)
            try {
                res = JSON.parse(res)
                if (res.id != undefined) {
                    setArgument('qttoken', key);
                    java.toast('\n\n密钥登录成功')
                    result['邮箱'] = res.email
                    putLoginInfo(JSON.stringify(result))
                } else {
                    throw new Error()
                }
            } catch (e) {
                java.log(e)
                java.toast("\n\n💔登录失败")
            }
        }
    } else if (flag && String(getKey(String(cookie.getCookie(base_url))))) {
        java.toast("\n\n当前✅️已登录，请🚫退出登录后重新登录");
        //checkStatus();
    } else if (flag) {
        java.toast("\n\n⛔️请先填写邮箱和密码");
    }
}





function applyCookieSettings() {
    let controlUrla = getArgument('controlUrl') || controlUrl;
    var cookieStr = String(cookie.getCookie(controlUrla));

    var cookieData = {};
    if (cookieStr && cookieStr !== 'null' && cookieStr !== 'undefined' && cookieStr !== '') {
        var pairs = cookieStr.split('; ');
        for (var i = 0; i < pairs.length; i++) {
            var pair = pairs[i];
            var eqIndex = pair.indexOf('=');
            if (eqIndex > -1) {
                var key = pair.substring(0, eqIndex).trim();
                var value = decodeURIComponent(pair.substring(eqIndex + 1).trim());
                cookieData[key] = value;
            }
        }
    }

    var displayConfig = [{
            key: 'server',
            label: '服务器',
            defaultValue: host[0]
        },
        {
            key: 'proxy',
            label: '访问模式',
            defaultValue: '云端'
        },
        {
            key: 'tab',
            label: '阅读模式',
            defaultValue: '小说'
        },
        {
            key: 'fqcommunity',
            label: '本章说',
            defaultValue: 'on'
        },
        {
            key: 'sources',
            label: '书源选择',
            defaultValue: '全部'
        },
        {
            key: 'fqpara',
            label: '段评显示',
            defaultValue: 'on'
        },
        {
            key: 'disabled_sources',
            label: '强制搜索',
            defaultValue: '0'
        },
        {
            key: 'reading',
            label: '同步书架',
            defaultValue: '0'
        },
        {
            key: 'info',
            label: '完整简介',
            defaultValue: 'on'
        }
    ];

    var valueMap = {
        // 访问模式
        '本地': '💻 本地',
        '云端': '☁️ 云端',

        // 开关状态
        'on': '✅ 开启',
        'off': '❌ 关闭',
        '1': '✅ 开启',
        '0': '❌ 关闭',

        // 频道类型
        '男频': '👨 男频',
        '女频': '👩 女频',

        // 内容类型
        '小说': '📖 小说',
        '听书': '🎧 听书',
        '漫画': '🎨 漫画',
        '短剧': '🎬 短剧',

        // 来源类型
        'vip': '💎 VIP专属',
        'svip': '👑 SVIP专属',
        '推荐': '⭐ 网友推荐',
        '全部': '📚 全部'
    };


    var displayLines = [];

    for (var i = 0; i < displayConfig.length; i++) {
        var config = displayConfig[i];
        var argumentValue = getArgument(config.key);
        var cookieValue = cookieData[config.key];
        var value = argumentValue || cookieValue || config.defaultValue;

        // 检测只补齐缺失配置，不能用旧 Cookie 覆盖用户当前选择。
        if (!argumentValue) {
            setArgument(config.key, cookieValue || config.defaultValue);
        }

        var displayValue = valueMap[value] || value;
        if (config.key === 'sources' && displayValue.length > 25) {
            displayValue = displayValue.substring(0, 25) + '...';
        }

        displayLines.push(config.label + ': ' + displayValue);
    }

    // 构建提示模板
    var template = '✨ 当前配置\n';
    template += '━━━━━━━━━━━━━━━━\n';
    template += displayLines.join('\n');
    template += '\n━━━━━━━━━━━━━━━━\n';
    template += '❤️当前应用的 *⚙️长按书源登录设置* 中的配置哦❤️'

    // 显示提示
    java.longToast(template);

    return displayLines.length;
}


