//退出登录
function logout() {
    // 登录成功时 token 会同步到所有线路，退出时必须逐个清除，避免切换线路后仍保持登录。
    var servers = [];
    try {
        servers = Array.isArray(host) ? host.slice() : [];
    } catch (e) {}
    try {
        var currentServer = String(getArgument('server') || '').trim();
        if (currentServer) servers.push(currentServer);
    } catch (e) {}

    var seenServers = {};
    for (var i = 0; i < servers.length; i++) {
        var server = String(servers[i] || '').trim().replace(/\/+$/, '');
        if (!server || seenServers[server]) continue;
        seenServers[server] = true;
        try { cookie.removeCookie(server); } catch (e) {}
        try { cookie.removeCookie(server + '/'); } catch (e) {}
    }

    // 清除可能按域名保存的第三方登录状态。
    var domains = [
        'fanqienovel.com', 'snssdk.com', '69shuba.com',
        'langge.uk', 'langge.tk', 'langge.cf', 'doubi.tk',
        '219.154.201.122'
    ];
    for (var d = 0; d < domains.length; d++) {
        try { cookie.removeCookie(domains[d]); } catch (e) {}
    }

    // 活动 token 不应在书源变量或登录信息中继续残留；邮箱密码保留以便下次登录。
    try {
        var variables = JSON.parse(String(source.getVariable() || '{}'));
        if (variables && typeof variables === 'object') {
            delete variables.qttoken;
            delete variables['密钥'];
            source.setVariable(JSON.stringify(variables));
        }
    } catch (e) {}
    try {
        var loginInfo = {};
        try { loginInfo = JSON.parse(String(source.getLoginInfo() || '{}')); } catch (e) {}
        if (result && typeof result === 'object') {
            for (var loginField in result) loginInfo[loginField] = result[loginField];
        }
        if (loginInfo && typeof loginInfo === 'object') {
            delete loginInfo['密钥'];
            delete loginInfo.qttoken;
            putLoginInfo(JSON.stringify(loginInfo));
        }
    } catch (e) {}

    java.toast("退出登录成功");
}

